#include <bits/stdc++.h>using namespace std;   void solve() {    int n;    if (!(cin >> n)) return;     vector<int> p(n), a(n);    for (int i = 0; i < n; i++) cin >> p[i];    for (int i = 0; i < n; i++) cin >> a[i];     int a_ptr = 0;     for (int i = 0; i < n; i++) {        if (a_ptr < n && p[i] == a[a_ptr]) {            int current_val = a[a_ptr];            while (a_ptr < n && a[a_ptr] == current_val) {                a_ptr++;            }        }    }      if (a_ptr == n) {        cout << "YES" << endl;    } else {        cout << "NO" << endl;    }} int main() {        ios_base::sync_with_stdio(false);    cin.tie(NULL);     int t;    if (!(cin >> t)) return 0;    while (t--) {        solve();    }    return 0;}